let memory={};let storageOK=true;
function read(key,fallback){if(Object.prototype.hasOwnProperty.call(memory,key))return memory[key];try{return JSON.parse(localStorage.getItem('gasto-'+key))??fallback}catch{return memory[key]??fallback}}
function write(key,value){memory[key]=value;try{localStorage.setItem('gasto-'+key,JSON.stringify(value))}catch{storageOK=false}}
const linkLang=new URLSearchParams(location.search).get('lang');
let lang=['de','en','fr'].includes(linkLang)?linkLang:read('lang','de');if(!['de','en','fr'].includes(lang))lang='de';
let completed=read('completed',[]);if(!Array.isArray(completed))completed=[];
let notes=read('notes',[]);if(!Array.isArray(notes))notes=[];
let selectedAnswers=read('answers-v2',{}),quickChoice=null,currentScene=0,pairDish=0,pairVariant=0,pairMode='wine',pairDrink=0,pairRevealed=false,aromaIndex=0,deleted=null;
const $=s=>document.querySelector(s);const txt=x=>x?.[lang]??x??'';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow='<svg class="arrow" viewBox="0 0 30 16" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="M1 8h26M21 2l6 6-6 6"/></svg>';
const art=(name,cls='')=>`<img class="${cls}" src="assets/${name}.svg?v=ink-6" alt="" aria-hidden="true">`;
function shell(){document.documentElement.lang=lang;$('#header').innerHTML=`<a class="wordmark serif" href="#home" aria-label="SALONFORMAT"><span>salon</span><span>format.</span></a><nav aria-label="${txt(T('Hauptnavigation','Main navigation','Navigation principale'))}">${UI.nav.map((n,i)=>`<a href="#${['journey','lab','table','notes'][i]}" ${location.hash.includes(['journey','lab','table','notes'][i])?'aria-current="page"':''}>${txt(n)}</a>`).join('')}</nav><div class="languages" aria-label="Language">${['de','en','fr'].map(l=>`<button data-lang="${l}" lang="${l}" aria-label="${{de:'Deutsch',en:'English',fr:'Français'}[l]}" aria-pressed="${lang===l}">${l.toUpperCase()}</button>`).join('')}</div>`;$('#footer').innerHTML=`<a class="footer-brand" href="https://salonformat.at/" aria-label="${txt(T('Zur Website von SALONFORMAT','Visit SALONFORMAT','Visiter le site SALONFORMAT'))}">salonformat. ↗</a><span>${txt(UI.edition)}</span><a href="#sources">${txt(UI.sources)}</a>`;document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{saveDraft();lang=b.dataset.lang;write('lang',lang);render(false);document.querySelector(`[data-lang="${lang}"]`)?.focus({preventScroll:true})});}
function home(){let next=LESSONS.find(l=>!completed.includes(l.id))||LESSONS[0];return `<section class="opening"><div class="opening-copy"><h1>${txt(UI.home)}</h1><p class="intro">${txt(T('Ein gutes Gericht verdient einen aufmerksamen Gastgeber. Entdecke die Welt der Aromen, lerne passende Getränke zu empfehlen und gewinne Sicherheit im Service.','A great dish deserves a thoughtful host. Explore flavour, learn to recommend drinks and build confidence in the dining room.','Un beau plat mérite un accueil attentif. Explorez les saveurs, apprenez à conseiller les boissons et gagnez en assurance en salle.'))}</p><a class="primary" href="#beginning">${txt(T('Die Experience entdecken','Discover the experience','Découvrir l’expérience'))}${arrow}</a><p class="signature">${txt(T('Für den Restaurantservice. Von SALONFORMAT.','For restaurant service. By SALONFORMAT.','Pour le service en restaurant. Par SALONFORMAT.'))}</p></div><div class="opening-art table-scene">${art('table-ink','table-illustration')}<span class="table-caption">à table.</span></div></section><section class="onboarding" id="beginning"><div class="section-head"><h2>${txt(T('Du lernst für den nächsten Gast.','Learn for the guest in front of you.','Apprendre pour mieux recevoir.'))}</h2><p>${txt(T('Du beginnst im Service eines gehobenen Restaurants oder möchtest dein Wissen auffrischen? Dieser Lernweg verbindet kurze Erklärungen mit Entscheidungen am Tisch und Übungen in deinem Betrieb. Du brauchst kein Vorwissen über Wein.','Starting in fine dining, or refreshing your knowledge? This journey combines short explanations, decisions at the table and practical tasks in your restaurant. No previous wine knowledge is needed.','Vous débutez dans un restaurant gastronomique ou souhaitez revoir vos bases ? Ce parcours associe explications, situations de service et exercices dans votre établissement. Aucune connaissance préalable du vin n’est nécessaire.'))}</p></div><ol class="learning-steps"><li><span>01</span><h3>${txt(T('Verstehen','Understand','Comprendre'))}</h3><p>${txt(T('Lies eine kurze Einführung. Du erfährst, worauf es ankommt und wie du es einem Gast verständlich erklärst.','Read a short introduction. Learn what matters and how to explain it clearly to a guest.','Lisez une courte introduction. Découvrez les points essentiels et comment les expliquer simplement à un convive.'))}</p></li><li><span>02</span><h3>${txt(T('Ausprobieren','Try it out','Essayer'))}</h3><p>${txt(T('Wähle eine Antwort im Gästegespräch oder erkunde ein Pairing. Du bekommst eine Erklärung zu deiner Entscheidung und kannst es erneut versuchen.','Choose a response in a guest conversation or explore a pairing. Get an explanation of your choice and try again whenever you wish.','Répondez à une question de service ou essayez un accord. Lisez ensuite l’explication et recommencez si vous le souhaitez.'))}</p></li><li><span>03</span><h3>${txt(T('Im Restaurant üben','Practise at work','Pratiquer au restaurant'))}</h3><p>${txt(T('Erledige drei kleine Aufgaben mit den Informationen und Materialien, die in deinem Betrieb vorhanden sind. Halte fest, was dir hilft, und schließe die Einheit ab, wenn du sie erarbeitet hast.','Complete three small tasks using information and materials already available at work. Record what helps you, then finish the lesson once you have worked through it.','Réalisez trois petits exercices avec les informations et le matériel déjà disponibles dans votre établissement. Gardez une trace de ce qui vous aide, puis terminez la séquence une fois le travail effectué.'))}</p></li></ol><div class="learning-details"><p>${txt(T('Plane für den digitalen Teil einer Einheit etwa 5–10 Minuten ein. Die Praxisaufgaben verteilst du über deine ersten Dienste. Verkostungen sprichst du mit deinem Team ab; Alkohol ist dafür nicht erforderlich.','Allow about 5–10 minutes for the digital part of a lesson. Spread the practical tasks across your first shifts. Agree tastings with your team; alcohol is not required.','Prévoyez environ 5 à 10 minutes pour la partie numérique d’une séquence. Répartissez la pratique sur vos premiers services. Organisez les dégustations avec votre équipe ; l’alcool n’est pas nécessaire.'))}</p><p>${txt(T('Du kannst jedes Kapitel einzeln öffnen. Du kannst jederzeit pausieren oder die Sprache wechseln. Antworten, Fortschritt und Notizen werden in diesem Browser gespeichert.','You can open any chapter. Pause or change language at any time. Answers, progress and notes are saved in this browser.','Vous pouvez ouvrir chaque chapitre. Vous pouvez faire une pause ou changer de langue à tout moment. Réponses, progression et notes sont enregistrées dans ce navigateur.'))}</p></div></section><section class="invitation"><div><h2>${txt(T('Vom ersten Willkommen bis zum letzten Glas.','From the first welcome to the final glass.','Du premier accueil au dernier verre.'))}</h2><p>${txt(T('Zwanzig Einheiten führen dich durch die wichtigsten Aufgaben im Service: vorbereiten, Produkte kennen, Geschmack beschreiben, Getränke empfehlen und Gäste aufmerksam betreuen.','Twenty lessons cover the essentials of service: preparation, ingredients, describing flavour, recommending drinks and looking after guests.','Vingt séquences pour découvrir les bases du service : se préparer, connaître les produits, décrire les saveurs, conseiller les boissons et prendre soin des clients.'))}</p><div class="actions"><a class="primary" href="#lesson/${next.id}">${txt(completed.length?UI.continue:T('Mit dem Empfang beginnen','Begin with the welcome','Commencer par l’accueil'))}${arrow}</a><a href="#journey">${txt(T('Alle Kapitel ansehen','View all chapters','Voir tous les chapitres'))}</a></div></div><div class="invitation-art">${art('oyster')}<p>${txt(T('Beobachten. Verstehen. Ausprobieren.','Observe. Understand. Practise.','Observer. Comprendre. Essayer.'))}</p></div></section><section class="prototype-note" id="prototype" tabindex="-1" aria-labelledby="prototype-title"><div class="prototype-visible"><h2 id="prototype-title">${txt(T('Ein Prototyp. Für euer Restaurant anpassbar.','A prototype, tailored to your restaurant.','Un prototype à adapter à votre restaurant.'))}</h2><div><p>${txt(T('Diese Experience ist ein Prototyp von SALONFORMAT. Ich passe Inhalte, Aufgaben und Gestaltung an euer Restaurant an – an eure Speise- und Getränkekarte, eure Abläufe im Service, die Praxis in eurem Haus und die Sprachen eures Teams.','This experience is a prototype by SALONFORMAT. I can adapt the content, exercises and design to your restaurant’s food and drinks menus, service routines, ways of working and team languages.','Cette expérience est un prototype créé par SALONFORMAT. Je peux adapter les contenus, les exercices et la présentation à votre restaurant : votre carte, vos boissons, vos habitudes de service et les langues de votre équipe.'))}</p><p>${txt(T('Die fachlichen Inhalte stimmen wir gemeinsam mit Küche und Serviceleitung ab. So wird daraus eine Einführung oder Auffrischung, die zu eurem Betrieb passt.','Together with your kitchen and service team, we review the practical content to create an introduction or refresher that fits your restaurant.','Les contenus métier sont à travailler ensemble, avec votre cuisine et votre responsable de salle, pour créer un parcours d’accueil ou de remise à niveau adapté à votre établissement.'))}</p><a class="text-button" href="https://salonformat.at/">${txt(T('Mehr über SALONFORMAT','Visit SALONFORMAT','Découvrir SALONFORMAT'))}${arrow}</a></div></div></section>`}
function journey(full=true){return `<section class="section">${completed.length===LESSONS.length?`<div class="finish-banner"><h2>${txt(UI.completedTitle)}</h2><p>${txt(UI.completedText)}</p></div>`:''}<div class="section-head"><h${full?'1':'2'}>${txt(UI.journey)}</h${full?'1':'2'}><div><p>${txt(UI.journeyIntro)}</p><div class="progress"><progress max="${LESSONS.length}" value="${completed.length}" aria-label="${txt(T('Lernfortschritt','Learning progress','Progression'))}"></progress><span>${completed.length} / ${LESSONS.length} ${txt(UI.done)}</span></div></div></div>${UI.chapters.map((c,g)=>`<section class="chapter"><div class="chapter-title"><small>${String(g+1).padStart(2,'0')} / 05</small><h3>${txt(c)}</h3>${art(['herb','fish','wine','oyster','lemon'][g])}</div><div>${LESSONS.filter(l=>l.group===g).map(l=>`<a class="lesson-row" href="#lesson/${l.id}"><span class="row-number">${String(LESSONS.indexOf(l)+1).padStart(2,'0')}</span><span class="row-title">${txt(l.title)}</span><span class="row-meta">${completed.includes(l.id)?txt(UI.done):'5–10 '+txt(UI.minutes)}</span></a>`).join('')}</div></section>`).join('')}<p class="hint">${txt(UI.privacy)}</p></section>`}
function lessonPage(id){const l=LESSONS.find(x=>x.id===id);if(!l)return home();const chosen=selectedAnswers[id];const pass=chosen===l.answer;return `<div class="page-title"><a class="back" href="#journey">${txt(UI.back)}</a><h1>${txt(l.title)}</h1><p>${txt(l.lead)}</p></div><div class="lesson-layout"><article class="reading"><h2>${txt(UI.know)}</h2>${txt(l.body).split('||').map(p=>`<p>${p}</p>`).join('')}<div class="practice"><h2>${txt(UI.practice)}</h2><p>${txt(l.practice)}</p></div></article><aside class="lesson-aside">${art(l.art)}<div class="sources-small"><h3>${txt(UI.source)}</h3>${l.sources.map(i=>`<a href="${SOURCES[i].url}" target="_blank" rel="noopener noreferrer">${SOURCES[i].name}</a>`).join('')}</div></aside></div><section class="exercise"><div class="exercise-inner"><h2>${txt(UI.decide)}</h2><p class="question">${txt(l.q)}</p><div class="options">${l.options.map((o,i)=>`<button class="option ${chosen===i?'selected':''}" data-answer="${i}" data-lesson="${id}" aria-pressed="${chosen===i}"><span>${String.fromCharCode(65+i)}</span><span>${txt(o)}</span></button>`).join('')}</div><div class="feedback" aria-live="polite">${chosen!==undefined?`<strong>${txt(pass?UI.correct:UI.retry)}</strong><p>${txt(l.feedbackByChoice?.[chosen] || l.feedback)}</p>`:''}</div></div></section><section class="lesson-end"><label for="reflection">${txt(UI.reflect)}</label><p class="hint">${txt(UI.reflectHint)}</p><textarea id="reflection" data-draft="${id}" rows="4">${esc(read('draft-'+id,''))}</textarea><div class="actions"><button class="text-button" id="save-reflection" data-lesson="${id}">${txt(UI.save)}</button><button class="primary" id="complete" data-lesson="${id}" ${!pass&&!completed.includes(id)?'disabled':''}>${txt(completed.includes(id)?UI.next:UI.finish)}${arrow}</button></div><p class="local-status" id="note-status" role="status"></p><p class="hint">${txt(UI.completeHint)}</p></section>`}
function saveDraft(){let t=$('[data-draft]');if(t)write('draft-'+t.dataset.draft,t.value);let n=$('#note-input');if(n)write('draft-notes',n.value)}
function addNote(text,lessonId=''){if(!text.trim())return false;notes.unshift({id:crypto.randomUUID(),text:text.trim(),lesson:lessonId,date:new Date().toISOString()});write('notes',notes);return true}
function notesPage(){return `<div class="page-title"><h1>${txt(UI.notebook)}</h1><p>${txt(UI.noteIntro)}</p></div><div class="notebook-layout"><div class="notes-form"><label for="note-input">${txt(UI.noteLabel)}</label><textarea id="note-input" rows="7">${esc(read('draft-notes',''))}</textarea><div class="actions"><button class="primary" id="save-note">${txt(UI.save)}${arrow}</button><button class="text-button" id="export-notes" ${notes.length?'':'disabled'}>${txt(UI.export)}</button></div><p class="hint">${txt(UI.privacy)}</p><p class="local-status" id="note-status" role="status"></p>${art('herb')}</div><div>${deleted?`<button class="text-button" id="undo-delete">${txt(UI.undo)}</button>`:''}${notes.length?notes.map(n=>`<article class="note"><time>${new Intl.DateTimeFormat(lang,{dateStyle:'medium'}).format(new Date(n.date))}</time>${n.lesson?`<div class="hint">${txt(LESSONS.find(l=>l.id===n.lesson)?.title)||''}</div>`:''}<p>${esc(n.text)}</p><button class="text-button" data-delete="${n.id}">${txt(UI.remove)}</button></article>`).join(''):`<p class="empty">${txt(UI.empty)}</p>${art('lemon')}`}</div></div>`}
function sourcesPage(){return `<div class="page-title"><h1>${txt(UI.sources)}</h1><p>${txt(T('Gute Gastlichkeit verbindet Wissen, Übung und das Gespür für den einzelnen Menschen.','Good hospitality brings together knowledge, practice and an understanding of the individual.','L’hospitalité associe savoir, pratique et attention à chaque personne.'))}</p></div><section class="source-list"><p class="source-note">${txt(T('Diese erste Edition vermittelt Grundlagen für die gehobene Gastronomie. Die Übungen und Gesprächssituationen sind eigens entwickelte Lernbeispiele. Sie sind keine zertifizierte Berufsausbildung. Die praktische Einweisung sowie aktuelle Hausstandards und örtliche Vorgaben bleiben maßgeblich. Eine fachliche Durchsicht mit Küche und Serviceleiter ist vor dem betrieblichen Einsatz vorgesehen.','This first edition introduces fine-dining service fundamentals. Exercises and conversations are original learning examples, not an accredited professional qualification. Practical instruction, current house standards and local requirements remain essential. Review with the kitchen and service manager is intended before workplace use.','Cette première édition présente les bases du service gastronomique. Les exercices et dialogues sont des situations pédagogiques originales, et non une qualification professionnelle reconnue. La formation pratique, les usages de la maison et les règles locales restent essentiels. Une relecture avec la cuisine et le responsable de salle est prévue avant utilisation en établissement.'))}</p>${SOURCES.map(s=>`<article><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.name}</a><p>${txt(s.topic)}</p></article>`).join('')}<p class="hint">${txt(T('Eigene SVG-Linienzeichnungen. Keine Verbindung zu den genannten Bildungseinrichtungen. Recherche: September 2026.','Original SVG line drawings. No affiliation with the educational organisations mentioned. Research: September 2026.','Dessins au trait originaux en SVG. Aucun lien avec les organismes de formation cités. Recherche : septembre 2026.'))}</p></section>`}
function bind(){document.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>{quickChoice=+b.dataset.quick;render(false)});document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{saveDraft();selectedAnswers[b.dataset.lesson]=+b.dataset.answer;write('answers-v2',selectedAnswers);render(false);document.querySelector(`[data-answer="${b.dataset.answer}"]`)?.focus({preventScroll:true})});$('#complete')?.addEventListener('click',e=>{let id=e.currentTarget.dataset.lesson;if(typeof completeDigital==='function'){completeDigital(id);return;}if(!completed.includes(id)&&(typeof canComplete==='function'?!canComplete(id):selectedAnswers[id]!==LESSONS.find(l=>l.id===id).answer))return;saveDraft();if(!completed.includes(id)){completed.push(id);write('completed',completed)}let i=LESSONS.findIndex(l=>l.id===id);location.hash=i<LESSONS.length-1?'lesson/'+LESSONS[i+1].id:'journey'});$('#reflection')?.addEventListener('input',saveDraft);$('#note-input')?.addEventListener('input',saveDraft);$('#save-reflection')?.addEventListener('click',e=>{if(addNote($('#reflection').value,e.currentTarget.dataset.lesson)){$('#note-status').textContent=txt(storageOK?UI.saved:UI.storageError);$('#reflection').value='';saveDraft()}});$('#save-note')?.addEventListener('click',()=>{if(addNote($('#note-input').value)){write('draft-notes','');render(false);$('#note-status').textContent=txt(storageOK?UI.saved:UI.storageError)}});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{deleted=notes.find(n=>n.id===b.dataset.delete);notes=notes.filter(n=>n.id!==b.dataset.delete);write('notes',notes);render(false)});$('#undo-delete')?.addEventListener('click',()=>{if(deleted){notes.unshift(deleted);deleted=null;write('notes',notes);render(false)}});$('#export-notes')?.addEventListener('click',()=>{const blob=new Blob([notes.map(n=>`${n.date.slice(0,10)}\n${n.text}`).join('\n\n---\n\n')],{type:'text/plain;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='SALONFORMAT-notes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});if(typeof bindLab==='function')bindLab();}
function render(scroll=true){shell();let route=location.hash.slice(1)||'home';let html=route.startsWith('lesson/')?lessonPage(route.split('/')[1]):route==='journey'?journey():route==='notes'?notesPage():route==='sources'?sourcesPage():route==='lab'&&typeof labPage==='function'?labPage():route==='table'&&typeof tablePage==='function'?tablePage():home();$('#main').innerHTML=html;bind();if(scroll){window.scrollTo(0,0);$('#main').focus({preventScroll:true})}}
window.addEventListener('hashchange',()=>{if(location.hash==='#beginning'){document.getElementById('beginning')?.scrollIntoView({behavior:'smooth'});return}if(location.hash==='#main'){document.getElementById('main').focus();return}saveDraft();render()});render();
